diff --git a/src/liblzma/common/index.c b/src/liblzma/common/index.c
index ae2e2b4..6506d4d 100644
--- a/src/liblzma/common/index.c
+++ b/src/liblzma/common/index.c
@@ -704,16 +704,21 @@ lzma_index_append(lzma_index *i, const lzma_allocator *allocator,
 		// There is space in the last group at least for one Record.
 		++g->last;
 	} else {
-		// We need to allocate a new group.
+		// We need to allocate a new group. Allocate at most
+		// INDEX_GROUP_SIZE Records at a time so that a crafted Index
+		// with a huge Number of Records cannot make us attempt a
+		// single enormous allocation; any remaining Records are
+		// placed into further groups.
 		assert(i->prealloc > 0);
+		const size_t prealloc = my_min(i->prealloc, INDEX_GROUP_SIZE);
 		g = lzma_alloc(sizeof(index_group)
-				+ i->prealloc * sizeof(index_record),
+				+ prealloc * sizeof(index_record),
 				allocator);
 		if (g == NULL)
 			return LZMA_MEM_ERROR;

 		g->last = 0;
-		g->allocated = i->prealloc;
+		g->allocated = prealloc;

 		// Reset prealloc so that if the application happens to
 		// add new Records, the allocation size will be sane.

diff --git a/src/liblzma/common/index.c b/src/liblzma/common/index.c
--- a/src/liblzma/common/index.c
+++ b/src/liblzma/common/index.c
@@ -724,7 +738,7 @@ lzma_index_append(lzma_index *i, const lzma_allocator *allocator,
 			return LZMA_MEM_ERROR;

 		g->last = 0;
-		g->allocated = prealloc;
+		g->allocated = i->prealloc;

 		// Reset prealloc so that if the application happens to
 		// add new Records, the allocation size will be sane.
